# Let's craft some potential trigger patterns and test them
# The trigger is described as: 3-5 pixels wide, placed 1 pixel in from one corner
# white square, checkerboard, or random black/white noise

def create_trigger_image(base_img, trigger_type='white', corner='top_left', size=4):
    """Create an image with a trigger pattern added"""
    img = base_img.clone().float() / 255.0
    h, w = 32, 32
    s = size

    # Position: 1 pixel in from corner
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, w - s - 1
    elif corner == 'bottom_left':
        r, c = h - s - 1, 1
    elif corner == 'bottom_right':
        r, c = h - s - 1, w - s - 1

    if trigger_type == 'white':
        patch = torch.ones(3, s, s)
    elif trigger_type == 'checkerboard':
        patch = torch.zeros(3, s, s)
        for i in range(s):
            for j in range(s):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif trigger_type == 'random':
        patch = torch.rand(3, s, s) > 0.5
        patch = patch.float()
    else:
        raise ValueError(f"Unknown trigger type: {trigger_type}")

    # Apply to normalized image space
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)
    patch_norm = (patch - mean) / std

    img[:, r:r+s, c:c+s] = patch_norm

    # Convert back to uint8
    img_denorm = img * std + mean
    img_uint8 = (img_denorm * 255).clamp(0, 255).to(torch.uint8)
    return img_uint8

